import{_ as t,a as r,o as i,ai as a}from"./chunks/framework.BbOtTPsL.js";const l=JSON.parse('{"title":"Product Review","description":"","frontmatter":{"outline":false,"apiType":"rest"},"headers":[],"relativePath":"api/rest-api/shop/product-reviews/index.md","filePath":"api/rest-api/shop/product-reviews/index.md","lastUpdated":1782473079000}'),d={name:"api/rest-api/shop/product-reviews/index.md"};function o(s,e,p,n,c,h){return i(),r("div",null,e[0]||(e[0]=[a('<h1 id="product-review" tabindex="-1">Product Review <a class="header-anchor" href="#product-review" aria-label="Permalink to &quot;Product Review&quot;">​</a></h1><p>The Product Review menu covers the ratings and reviews shoppers leave on products. Anyone can read the reviews on a product; a logged-in customer can write a new review and edit or delete their own.</p><h2 id="read-vs-write" tabindex="-1">Read vs. write <a class="header-anchor" href="#read-vs-write" aria-label="Permalink to &quot;Read vs. write&quot;">​</a></h2><ul><li><strong>Reading</strong> reviews (list for a product, or a single review) is public — only the storefront key is needed.</li><li><strong>Writing</strong> a review, and updating or deleting one, requires an authenticated customer (a customer Bearer token). A customer may only edit or delete a review they created.</li></ul><p>New reviews are typically held for moderation before they appear publicly, depending on the store&#39;s settings.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Method &amp; Path</th><th>Description</th></tr></thead><tbody><tr><td><a href="/api/rest-api/shop/product-reviews/get-product-reviews.html">Get Product Reviews</a></td><td><code>GET /api/shop/products/{id}/reviews</code></td><td>List the reviews on a product.</td></tr><tr><td><a href="/api/rest-api/shop/product-reviews/get-product-review.html">Get Product Review</a></td><td><code>GET /api/shop/reviews/{id}</code></td><td>A single review by id.</td></tr><tr><td><a href="/api/rest-api/shop/product-reviews/create-product-review.html">Create Product Review</a></td><td><code>POST /api/shop/products/{id}/reviews</code></td><td>Submit a review for a product.</td></tr><tr><td><a href="/api/rest-api/shop/product-reviews/update-product-review.html">Update Product Review</a></td><td><code>PUT /api/shop/reviews/{id}</code></td><td>Edit the customer&#39;s own review.</td></tr><tr><td><a href="/api/rest-api/shop/product-reviews/delete-product-review.html">Delete Product Review</a></td><td><code>DELETE /api/shop/reviews/{id}</code></td><td>Remove the customer&#39;s own review.</td></tr></tbody></table><p>Read endpoints need only the storefront key; create, update and delete require a customer Bearer token — see <a href="/api/rest-api/authentication.html">Authentication</a>.</p>',8)]))}const w=t(d,[["render",o]]);export{l as __pageData,w as default};
